import{_ as h,C as c,o as i,c as p,a9 as a,b as o,w as t,a as s,E as n,a8 as d}from"./chunks/framework.BOiBTRPC.js";const k=JSON.parse('{"title":"ML Training Pipelines in Production","description":"TFX-style pipeline decomposition, data validation gates, feature engineering in the pipeline, model versioning and registries, orchestration, CI/CD for ML, and the monitoring hand-off.","frontmatter":{"title":"ML Training Pipelines in Production","description":"TFX-style pipeline decomposition, data validation gates, feature engineering in the pipeline, model versioning and registries, orchestration, CI/CD for ML, and the monitoring hand-off."},"headers":[],"relativePath":"system-design/ml-pipelines.md","filePath":"system-design/ml-pipelines.md"}'),u={name:"system-design/ml-pipelines.md"};function m(g,e,f,b,y,w){const r=c("Mermaid"),l=c("QuizCard");return i(),p("div",null,[e[5]||(e[5]=a('<h1 id="ml-training-pipelines-in-production" tabindex="-1">ML Training Pipelines in Production <a class="header-anchor" href="#ml-training-pipelines-in-production" aria-label="Permalink to &quot;ML Training Pipelines in Production&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — <a href="/Data-Knowledge/system-design/ml-systems.html">ML &amp; GenAI System Design</a> covered the system around the model; this chapter covers the pipeline that <em>produces</em> the model. Production retraining is a data pipeline with extra gates — data validation, transform reuse, model evaluation, infra validation — and most of its components are things a data engineer already knows how to build. The failure modes are also familiar: silent bad data, unreproducible artifacts, and deploys nobody can roll back.</p></blockquote><h2 id="a-model-is-not-a-pipeline" tabindex="-1">A model is not a pipeline <a class="header-anchor" href="#a-model-is-not-a-pipeline" aria-label="Permalink to &quot;A model is not a pipeline&quot;">​</a></h2><p>A notebook trains <em>a</em> model. A pipeline produces models <strong>repeatedly, reproducibly, and with an audit trail</strong>. The book&#39;s framing: an ML pipeline runs from ingestion of new training data to feedback on how the deployed model performs — it is a recurring cycle, not a one-shot run.</p><p>Pipelines earn their complexity when:</p><ul><li>The model has users, so it needs continuous updates and fine-tuning as the world changes.</li><li>Datasets or compute are large enough that runs must scale and be resumable.</li><li>Repeatability and audit trails matter — which data, which code, which config produced this artifact.</li></ul><p>A model you train twice a year for a static domain can stay a script. The trigger to invest is <strong>retraining frequency</strong> — every manual validation, deploy, or analysis step is a step a data scientist repeats forever instead of building the next model.</p><h2 id="the-tfx-style-component-decomposition" tabindex="-1">The TFX-style component decomposition <a class="header-anchor" href="#the-tfx-style-component-decomposition" aria-label="Permalink to &quot;The TFX-style component decomposition&quot;">​</a></h2><p>TensorFlow Extended (TFX) is the reference implementation for thinking about this — even if you never use it, its component boundaries name the gates every production training pipeline needs. Each component is a step with typed input and output <strong>artifacts</strong>; the orchestrator chains them via artifact dependencies, not hand-wired ordering.</p>',9)),(i(),o(d,null,{default:t(()=>[n(r,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20EG%5B%22ExampleGen%3A%20ingest%20%2B%20split%20train%20and%20eval%22%5D%20--%3E%20SG%5B%22StatisticsGen%3A%20descriptive%20stats%20over%20full%20data%22%5D%0A%20%20%20%20SG%20--%3E%20SCG%5B%22SchemaGen%3A%20infer%20schema%22%5D%0A%20%20%20%20SCG%20--%3E%20EV%5B%22ExampleValidator%3A%20anomalies%20vs%20schema%22%5D%0A%20%20%20%20SCG%20--%3E%20TR%5B%22Transform%3A%20feature%20engineering%20graph%22%5D%0A%20%20%20%20EV%20--%3E%20TR%0A%20%20%20%20TR%20--%3E%20TRN%5B%22Trainer%3A%20fit%20model%22%5D%0A%20%20%20%20TRN%20--%3E%20TU%5B%22Tuner%3A%20hyperparameter%20search%22%5D%0A%20%20%20%20TU%20--%3E%20EVAL%5B%22Evaluator%3A%20metrics%2C%20slices%2C%20bless%20or%20reject%22%5D%0A%20%20%20%20EVAL%20--%3E%20IV%5B%22InfraValidator%3A%20loads%20on%20real%20serving%20binary%22%5D%0A%20%20%20%20IV%20--%3E%7C%22blessed%22%7C%20P%5B%22Pusher%3A%20deploy%20to%20serving%22%5D%0A%20%20%20%20EVAL%20-.-%3E%7C%22not%20blessed%22%7C%20X%5B%22Stop%20%E2%80%94%20model%20never%20ships%22%5D%0A%20%20%20%20subgraph%20MLMD%5B%22ML%20Metadata%20store%22%5D%0A%20%20%20%20%20%20%20%20M%5B%22artifacts%20%2B%20executions%20%2B%20lineage%22%5D%0A%20%20%20%20end%0A%20%20%20%20EG%20-.-%3E%20M%0A%20%20%20%20TR%20-.-%3E%20M%0A%20%20%20%20EVAL%20-.-%3E%20M%0A%20%20%20%20P%20-.-%3E%20M%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=a('<p>Why each gate exists — every one answers a different question:</p><table tabindex="0"><thead><tr><th>Component</th><th>Question it answers</th><th>What it produces</th><th>Skip it and…</th></tr></thead><tbody><tr><td>ExampleGen</td><td>What data are we training on?</td><td>Versioned train/eval splits</td><td>No data snapshot → no reproducibility</td></tr><tr><td>StatisticsGen</td><td>What does the data look like?</td><td>Full-pass stats (mean, stddev, categories)</td><td>Downstream gates have nothing to compare</td></tr><tr><td>SchemaGen</td><td>What <em>should</em> the data look like?</td><td>Inferred schema: types, presence, domains</td><td>Every downstream check is hand-coded</td></tr><tr><td>ExampleValidator</td><td>Is this run&#39;s data broken?</td><td>Anomaly report; can halt the pipeline</td><td>Bad data silently trains a bad model</td></tr><tr><td>Transform</td><td>How do raw features become model inputs?</td><td>Transform graph + transformed data</td><td>Preprocessing drifts between training and serving</td></tr><tr><td>Trainer</td><td>Fit the model</td><td>SavedModel</td><td>—</td></tr><tr><td>Tuner</td><td>Are the hyperparameters right?</td><td>Best trial&#39;s hyperparameters</td><td>One-shot guesses left on the table</td></tr><tr><td>Evaluator</td><td>Is this model <em>better</em> — overall and per slice?</td><td>Metrics + bless/reject verdict</td><td>Worse models replace good ones</td></tr><tr><td>InfraValidator</td><td>Does it actually load and serve?</td><td>Infra blessing</td><td>&quot;Works in Python, crashes the model server&quot;</td></tr><tr><td>Pusher</td><td>Ship it</td><td>Model in the serving location</td><td>—</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>The pipeline&#39;s real product isn&#39;t the model — it&#39;s the <strong>metadata store</strong>. Every component writes what it read, produced, and decided, which gives you lineage (&quot;which data trained this model?&quot;), caching (&quot;rerun only the failed component&quot;), and the artifact chain that makes a rollback meaningful. Teams that skip the metadata layer get the orchestration but none of the debuggability.</p></div><details class="details custom-block"><summary>The DAG is derived, not declared</summary><p>In TFX-style systems you don&#39;t write the dependency graph — you wire artifacts: <code>StatisticsGen(examples=example_gen.outputs[&quot;examples&quot;])</code> creates a data dependency automatically, and the orchestrator topologically sorts. ExampleValidator and Transform both consume SchemaGen&#39;s output but not each other&#39;s, so they run in parallel. Explicit task dependencies (<code>add_upstream_node</code>) exist only for orderings the artifact flow can&#39;t express.</p></details><h2 id="data-validation-as-a-pipeline-step-not-a-pre-flight-check" tabindex="-1">Data validation as a pipeline step, not a pre-flight check <a class="header-anchor" href="#data-validation-as-a-pipeline-step-not-a-pre-flight-check" aria-label="Permalink to &quot;Data validation as a pipeline step, not a pre-flight check&quot;">​</a></h2><p>This is the piece data pipelines and ML pipelines share most directly — and where the ML version goes further. In a plain data pipeline, validation answers &quot;is this batch loadable?&quot; In a training pipeline it answers &quot;is this batch <em>worth training on</em>?&quot; — and the answer can legitimately stop the pipeline before it spends GPU-hours on garbage.</p><p>The standard split (from TensorFlow Data Validation, which powers StatisticsGen → SchemaGen → ExampleValidator):</p><ol><li><strong>Compute statistics</strong> over the whole dataset (full pass, Beam-scale).</li><li><strong>Infer a schema</strong> — feature presence, type, valency, domain.</li><li><strong>Curate the schema by hand</strong> — the inferred schema is a starting point; a human who knows the data tightens domains and required fields. The curated schema becomes the contract every future run is checked against.</li><li><strong>Detect anomalies</strong> — single-dataset checks against the schema, and two-dataset comparisons for drift and skew.</li></ol><h3 id="skew-vs-drift-—-and-the-three-kinds-of-skew" tabindex="-1">Skew vs drift — and the three kinds of skew <a class="header-anchor" href="#skew-vs-drift-—-and-the-three-kinds-of-skew" aria-label="Permalink to &quot;Skew vs drift — and the three kinds of skew&quot;">​</a></h3><p><strong>Drift</strong> compares across time: this week&#39;s training data vs last week&#39;s. <strong>Skew</strong> compares across environments: training data vs serving data. Skew has three distinct types that need different detection methods:</p><table tabindex="0"><thead><tr><th>Skew type</th><th>What differs</th><th>How it&#39;s detected</th><th>Classic cause</th></tr></thead><tbody><tr><td>Schema skew</td><td>Training and serving data don&#39;t conform to the same schema — float in training, int in serving</td><td>Same machinery as anomaly detection: serving stats vs schema</td><td>Two code paths serialize features differently</td></tr><tr><td>Feature skew</td><td>Same entity, different feature <em>values</em> between training and serving</td><td>Join train and serving examples on an ID feature, compare values</td><td>Feature computed at different times, or a bug in one path</td></tr><tr><td>Distribution skew</td><td>The shape of a feature&#39;s distribution shifted</td><td>Statistical distance — Jensen–Shannon divergence (numeric), L-infinity distance (categorical) — over a threshold</td><td>Biased sampling, different sources, seasonality</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>Schema skew is the cheap one to catch and the one teams actually catch. Distribution skew and feature skew need the <em>two-dataset</em> comparison — a serving-side stats job — which most pipelines never build. That&#39;s why training-serving skew is the classic silent killer: nothing errors, the model just quietly scores a different distribution than it learned.</p></div><p>Decision rule on anomaly detection: a schema-level anomaly (unexpected feature, missing feature, wrong type) means <strong>stop the pipeline and page a human</strong> — the data contract broke. A distribution-level anomaly (statistically different but valid data) means the world changed — <strong>retrain</strong>, don&#39;t halt. The pipeline&#39;s value is encoding that distinction in the gate, not leaving it to whoever reads the alert.</p><h2 id="feature-engineering-inside-the-pipeline" tabindex="-1">Feature engineering <em>inside</em> the pipeline <a class="header-anchor" href="#feature-engineering-inside-the-pipeline" aria-label="Permalink to &quot;Feature engineering *inside* the pipeline&quot;">​</a></h2><p>The naive design preprocesses data in a script, saves the result, then trains. This splits feature logic from the model and guarantees that one day the training transform and the serving transform disagree — the preprocessing bug the book calls out as a classic manual-workflow failure: the model still predicts, it&#39;s just wrong.</p><p>The pipeline-native design makes preprocessing a <strong>component that emits two artifacts</strong>:</p>',16)),(i(),o(d,null,{default:t(()=>[n(r,{id:"mermaid-333",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20D%5B%22Raw%20training%20data%20%2B%20curated%20schema%22%5D%20--%3E%20T%5B%22Transform%20component%22%5D%0A%20%20%20%20UC%5B%22User%20transform%20code%22%5D%20--%3E%20T%0A%20%20%20%20T%20--%3E%20TD%5B%22Transformed%20data%20%E2%86%92%20Trainer%22%5D%0A%20%20%20%20T%20--%3E%20TG%5B%22Transform%20graph%3A%20vocabularies%2C%20means%2C%20bucket%20edges%20as%20constants%22%5D%0A%20%20%20%20TG%20--%3E%20SM%5B%22SavedModel%3A%20transform%20graph%20prepended%20to%20model%20graph%22%5D%0A%20%20%20%20TD%20--%3E%20SM%0A%20%20%20%20SM%20--%3E%20SRV%5B%22Serving%3A%20identical%20transform%20applied%20to%20every%20request%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=a('<p>Two mechanics make this work:</p><ul><li><strong>Full-pass analyzers.</strong> Normalizing by z-score needs the dataset&#39;s mean and stddev; vocabulary and quantile bucketing need a full pass too. These &quot;analyzers&quot; run <strong>once per training run</strong> over the whole dataset (Beam-scale), then get frozen into the transform graph as constants — they do <em>not</em> recompute per request at serving time.</li><li><strong>Graph shipping.</strong> The transform becomes part of the model artifact itself. The serving path applies the identical computation graph — same constants, same ops — so training-serving skew from preprocessing is <em>structurally impossible</em>, not just unlikely.</li></ul><div class="info custom-block"><p class="custom-block-title">ℹ️</p><p>This is the same problem a feature store solves by dual-materializing one feature definition (see <a href="/Data-Knowledge/system-design/ml-systems.html#feature-stores">ML &amp; GenAI System Design</a>). Transform-graph shipping solves it for in-model preprocessing; feature stores solve it for pre-computed features. Most real systems need both — the store for shared features, the in-graph transform for last-mile encoding.</p></div><h2 id="evaluation-gates-the-bless-or-reject-chain" tabindex="-1">Evaluation gates: the bless-or-reject chain <a class="header-anchor" href="#evaluation-gates-the-bless-or-reject-chain" aria-label="Permalink to &quot;Evaluation gates: the bless-or-reject chain&quot;">​</a></h2><p>Trainer output is just a candidate. Three separate gates stand between it and production, each catching a different failure:</p><table tabindex="0"><thead><tr><th>Gate</th><th>Checks</th><th>Fails when</th></tr></thead><tbody><tr><td>Evaluator</td><td>Metrics vs baseline — and per <strong>slice</strong> of the data</td><td>New model is worse overall, or better on average but broken on a segment</td></tr><tr><td>InfraValidator</td><td>The model loads and answers queries on the <em>actual serving binary</em>, in a sandboxed replica of the serving env</td><td>Model is metric-fine but incompatible with the production model server</td></tr><tr><td>Pusher (conditional)</td><td>Only runs if upstream gates blessed the model</td><td>Skipped entirely — the artifact exists but never reaches serving</td></tr></tbody></table><p>The per-slice check deserves emphasis: a churn model can beat the incumbent on overall accuracy while collapsing on one customer region. Slice metrics are the difference between &quot;model approved&quot; and &quot;model approved with a fairness regression nobody saw.&quot;</p><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Make the Pusher <em>conditional on the blessing artifact</em>, not on a human click. The evaluator emits a blessing artifact; the push step is declared in the graph but executes only when the blessing says go. That&#39;s the ML-pipeline version of a merge gate — the decision is data, the deploy is code.</p></div><h2 id="model-versioning-and-the-registry" tabindex="-1">Model versioning and the registry <a class="header-anchor" href="#model-versioning-and-the-registry" aria-label="Permalink to &quot;Model versioning and the registry&quot;">​</a></h2><p>&quot;Which model is in prod?&quot; needs a sharper answer than a filename. There&#39;s no industry-standard model version scheme — the book surveys several, all defensible:</p><table tabindex="0"><thead><tr><th>Scheme</th><th>Version increments when</th><th>Trade-off</th></tr></thead><tbody><tr><td>Semantic-style (MAJOR.MINOR.PIPELINE)</td><td>MAJOR: data/target schema change; MINOR: model improved; PIPELINE: training pipeline changed</td><td>Readable semantics, but &quot;improved&quot; needs a defined metric</td></tr><tr><td>Arbitrary grouping</td><td>Developer decides which models belong to a version line</td><td>Flexible; can hide architecture/input changes</td></tr><tr><td>Black-box functional</td><td>Model is a black-box function; new version iff the input→output contract changes</td><td>Clean API semantics; ignores retraining on new data</td></tr><tr><td>Pipeline-execution</td><td>Every successful pipeline run mints a version (TFX&#39;s style)</td><td>Automatic and complete; version numbers carry no meaning about what changed</td></tr></tbody></table><p>Two concepts matter more than the numbering:</p><ul><li><strong>Model lineage</strong> — the relationship set among the artifacts that produced the model: which code, which data snapshot, which preprocessing ops, which config. Lineage is what makes &quot;reproduce this model&quot; a query instead of an archaeology project. It covers training and evaluation; post-training operations (serving behavior) aren&#39;t part of it.</li><li><strong>Model registry</strong> — the central repository: versioned model artifacts + searchable metadata + approval gates + links back to the lineage store. The registry is where &quot;the current production model&quot; becomes a pointer you can atomically move — which is also what makes rollback a pointer-swap instead of a redeploy.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>A model artifact without its transform graph and feature schema isn&#39;t a version — it&#39;s a half-version. The unit you register, promote, and roll back is <strong>model + preprocessing + input contract together</strong>. Versioning only the weights is how teams end up unable to roll back to last month&#39;s model: it exists, but nobody knows what features it expects.</p></div><h2 id="orchestration-who-runs-the-dag" tabindex="-1">Orchestration: who runs the DAG <a class="header-anchor" href="#orchestration-who-runs-the-dag" aria-label="Permalink to &quot;Orchestration: who runs the DAG&quot;">​</a></h2><p>The orchestrator is the glue: it orders components by artifact dependencies, tracks execution state, <strong>caches component outputs so a failure reruns only the failed step</strong>, and schedules recurring runs. Training pipelines are DAGs for the same reason Airflow DAGs are — directed so ordering is guaranteed, acyclic so runs terminate.</p><table tabindex="0"><thead><tr><th>Orchestrator</th><th>Model</th><th>When it fits</th></tr></thead><tbody><tr><td>Interactive context (notebook)</td><td><em>You</em> are the orchestrator; run components in order yourself</td><td>Development and debugging only — never production</td></tr><tr><td>Apache Beam runner</td><td>Reuses the data-processing cluster you already have</td><td>Minimal setup; Beam already runs your heavy transforms</td></tr><tr><td>Kubeflow Pipelines</td><td>Each component = a container on Kubernetes; artifact lineage UI</td><td>You have K8s and want scaling + the metadata/lineage surface</td></tr><tr><td>Managed pipelines (Vertex et al.)</td><td>Kubeflow under the hood, infra abstracted away</td><td>You want the DAG semantics without running the platform</td></tr></tbody></table><p>Where does Airflow sit? It&#39;s the general-purpose scheduler many teams already run for <a href="/Data-Knowledge/dataops/orchestration.html">data orchestration</a>, and it <em>can</em> drive training pipelines (the TFX runtime supports generic orchestrators). The honest comparison:</p><ul><li><strong>Airflow</strong> wins on ubiquity, scheduling semantics, and fitting training into a broader data-platform DAG (e.g., train right after the dbt build that produces features — see <a href="/Data-Knowledge/dataops/dbt.html">dbt for Data Engineers</a>).</li><li><strong>Kubeflow/managed ML orchestrators</strong> win on ML-native primitives: artifact typing, lineage UI, component caching keyed on inputs, GPU scheduling, per-component containers.</li></ul><p>The dividing question: does your training pipeline need ML artifact semantics and GPU-aware per-step environments (→ ML orchestrator), or is it one stage in an existing data DAG where a containerized training task is enough (→ Airflow)? Picking per-pipeline is fine — the book notes switching orchestrators is usually a few lines, precisely because the pipeline definition is portable across them.</p><details class="details custom-block"><summary>Components should be containerized</summary><p>Level-1+ pipelines treat each component as its own runtime: containerized, with its own dependencies, decoupled from siblings. That&#39;s what lets a Transform step run Beam-on-Dataflow while the Trainer runs on a GPU node — and what makes dev-cluster execution match production. If your &quot;component&quot; only works inside one fat environment, you have a script with extra steps.</p></details><h2 id="the-kubeflow-platform-anatomy" tabindex="-1">The Kubeflow platform anatomy <a class="header-anchor" href="#the-kubeflow-platform-anatomy" aria-label="Permalink to &quot;The Kubeflow platform anatomy&quot;">​</a></h2><p>Kubeflow is not one tool — it is a bundle of Kubernetes-native components that each own a slice of the model development life cycle, glued together by custom resource definitions (CRDs) on one cluster. The <em>Kubeflow for Machine Learning</em> book&#39;s map:</p>',23)),(i(),o(d,null,{default:t(()=>[n(r,{id:"mermaid-601",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20K8S%5B%22Kubernetes%20cluster%20%E2%80%94%20Kubeflow%20namespace%22%5D%0A%20%20%20%20%20%20%20%20JH%5B%22JupyterHub%20%E2%80%94%20notebooks%20for%20exploration%2C%20notebook-as-stage%22%5D%0A%20%20%20%20%20%20%20%20KFP%5B%22Kubeflow%20Pipelines%20%E2%80%94%20DSL%20compiles%20to%20Argo%20workflows%2C%20components%20as%20containers%22%5D%0A%20%20%20%20%20%20%20%20KAT%5B%22Katib%20%E2%80%94%20experiments%2C%20suggestions%2C%20trials%2C%20NAS%22%5D%0A%20%20%20%20%20%20%20%20KFS%5B%22KFServing%20or%20KServe%20%E2%80%94%20InferenceService%20CRD%22%5D%0A%20%20%20%20%20%20%20%20CAN%5B%22Canary%20endpoint%20%E2%80%94%20canaryTrafficPercent%20ratcheted%200%20to%20100%22%5D%0A%20%20%20%20%20%20%20%20MDT%5B%22ML%20Metadata%20%E2%80%94%20artifact%20and%20execution%20lineage%22%5D%0A%20%20%20%20%20%20%20%20MIO%5B%22MinIO%20%E2%80%94%20object%20storage%20for%20step-to-step%20artifacts%22%5D%0A%20%20%20%20%20%20%20%20IST%5B%22Istio%20plus%20Knative%20%E2%80%94%20routing%2C%20scale%20to%20zero%22%5D%0A%20%20%20%20end%0A%20%20%20%20DS%5B%22Data%20scientist%22%5D%20--%3E%20JH%0A%20%20%20%20JH%20--%3E%7C%22containerize%20function%2C%20compile%20pipeline%22%7C%20KFP%0A%20%20%20%20KFP%20--%3E%20MIO%0A%20%20%20%20KFP%20--%3E%20MDT%0A%20%20%20%20KFP%20--%3E%20KAT%0A%20%20%20%20KFP%20--%3E%7C%22blessed%20model%20URI%22%7C%20KFS%0A%20%20%20%20KFS%20--%3E%7C%22canaryTrafficPercent%22%7C%20CAN%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[s(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=a('<p>The pieces worth internalizing:</p><ul><li><strong>Kubeflow Pipelines (KFP)</strong> sits on <strong>Argo Workflows</strong>, a container-native workflow CRD. KFP&#39;s value-add over raw Argo is a Python DSL that generates the YAML boilerplate, ML-specific hooks (typed outputs, <code>file_outputs</code> that shuttle artifacts through object storage), a recurring-run scheduler, and the experiment/lineage UI. Every pipeline you run is also visible as an Argo workflow — <code>argo list -n kubeflow</code> works — which is the debugging surface when the UI lies.</li><li><strong>Every component is a container.</strong> <code>func_to_container_op</code> wraps a Python function; <code>dsl.ContainerOp</code> runs any image in any language; <code>dsl.Condition</code> gates branches. Multilingual pipelines are the point — Spark for prep, TF for training, your own binary for publish.</li><li><strong>Katib</strong> treats hyperparameter tuning as a first-class CRD: an <strong>Experiment</strong> owns a search space plus objective metric, a <strong>Suggestion</strong> is one candidate config, a <strong>Trial</strong> is one training run of it. It is language-agnostic (the trial is just a Docker image), ships distributed-training and NAS support (DARTS, ENAS), and scales by being K8s-native — prototype on a laptop cluster, submit the same spec to production.</li><li><strong>KFServing/KServe</strong> serves models via an <code>InferenceService</code> CRD on Knative + Istio: serverless scale-to-zero, autoscaling replicas, and three deployment strategies from one spec — <code>default</code> only gives blue-green, <code>canary</code> with <code>canaryTrafficPercent: 0</code> gives a pinned experimental endpoint, <code>&gt; 0</code> gives true percentage-split canary you ratchet to 100.</li><li><strong>The glue is real infrastructure</strong>: MinIO stores inter-step artifacts, Istio routes canary traffic, ML Metadata records lineage. Installing Kubeflow means running all of it — which is why managed offerings exist.</li></ul><h2 id="pipeline-as-code-kfp-dsl-vs-the-tfx-model" tabindex="-1">Pipeline-as-code: KFP DSL vs the TFX model <a class="header-anchor" href="#pipeline-as-code-kfp-dsl-vs-the-tfx-model" aria-label="Permalink to &quot;Pipeline-as-code: KFP DSL vs the TFX model&quot;">​</a></h2><p>Same idea — the pipeline <em>is</em> code — different grain:</p><table tabindex="0"><thead><tr><th></th><th>TFX</th><th>Kubeflow Pipelines DSL</th></tr></thead><tbody><tr><td>What you write</td><td>Component wiring (ExampleGen → Trainer → Pusher) against prebuilt component classes</td><td>Python functions with <code>@dsl.pipeline</code>, steps as <code>ContainerOp</code>s — any image</td></tr><tr><td>What it compiles to</td><td>Orchestrator-specific config (Airflow DAG, Beam, KFP)</td><td>Argo workflow YAML — K8s-only</td></tr><tr><td>Contract between steps</td><td>Typed artifacts tracked in ML Metadata</td><td><code>file_outputs</code>/params — files shuttled via object storage; <code>step.after(x)</code> for side-effect ordering</td></tr><tr><td>Framework posture</td><td>TensorFlow-first, strong opinions</td><td>Framework- and language-agnostic by construction</td></tr><tr><td>Sweet spot</td><td>You want the gates (validation, bless/reject) designed for you</td><td>You have heterogeneous steps and want to define the gates yourself</td></tr></tbody></table><p>The two compose, they don&#39;t just compete: TFX components can run <em>on</em> KFP, and the book uses <code>ContainerOp</code> for anything TFX doesn&#39;t cover. The deeper difference — TFX ships an <em>opinionated component taxonomy</em>; KFP ships a <em>portable container DAG</em>. Pick TFX when its components are your pipeline; pick raw KFP when they aren&#39;t.</p><h2 id="airflow-vs-kubeflow-lineage-vs-scheduling-maturity" tabindex="-1">Airflow vs Kubeflow: lineage vs scheduling maturity <a class="header-anchor" href="#airflow-vs-kubeflow-lineage-vs-scheduling-maturity" aria-label="Permalink to &quot;Airflow vs Kubeflow: lineage vs scheduling maturity&quot;">​</a></h2><p>The earlier orchestrator table gave the one-line version; the book&#39;s case studies sharpen the trade:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Airflow</th><th>Kubeflow</th></tr></thead><tbody><tr><td>Scheduling</td><td>Mature cron semantics, catchup, backfill, rich trigger rules</td><td>Recurring runs are <strong>frequency-only</strong> — a daily run created at 10am runs at 10am daily; you specify <em>how often</em>, never <em>when</em></td></tr><tr><td>Artifact lineage</td><td>Task logs, XComs if you&#39;re lucky</td><td>First-class: artifact store, execution records, lineage UI per run</td></tr><tr><td>Step isolation</td><td>Tasks share the worker env (or KubernetesPodOperator DIY)</td><td>Every step is its own container and node pool — GPU stages get GPU nodes</td></tr><tr><td>Step caching</td><td>Rerun the task</td><td>Cache keyed on inputs — a rerun replays only changed steps</td></tr><tr><td>Data-scientist ergonomics</td><td>DAGs are a DE artifact</td><td>Notebook → pipeline is the designed path; DSL is Python they already write</td></tr><tr><td>Best fit</td><td>Training is one stage in a data DAG you already run</td><td>The pipeline <em>is</em> the product: ML artifacts, GPUs, experiments</td></tr></tbody></table><p>The honest split: Airflow&#39;s scheduler is years ahead; Kubeflow&#39;s <em>per-run</em> semantics (lineage, caching, containers, GPU scheduling) are years ahead. Many shops run both — Airflow owns the data calendar and triggers KFP runs for training.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>The executor abstraction leaks. Argo supports several container runtimes (Docker, kubelet, k8sapi, PNS — set via <code>containerRuntimeExecutor</code>), and the choice changes your pipeline&#39;s contract: the k8sapi executor can only pass parameters <strong>and save artifacts through files/volumes</strong>, while Docker passes params by value. Platforms without Docker APIs (OpenShift 4+) force a non-Docker executor — the same pipeline YAML can silently change what&#39;s persisted. Know your cluster&#39;s executor before assuming <code>file_outputs</code> behaves like the examples.</p></div><h2 id="kubernetes-native-trade-offs-—-and-the-failure-modes-the-book-walked-into" tabindex="-1">Kubernetes-native trade-offs — and the failure modes the book walked into <a class="header-anchor" href="#kubernetes-native-trade-offs-—-and-the-failure-modes-the-book-walked-into" aria-label="Permalink to &quot;Kubernetes-native trade-offs — and the failure modes the book walked into&quot;">​</a></h2><p>K8s gives you GPU nodes, per-step isolation, and scale-to-zero serving. The bill:</p><ul><li><strong>Resource requests are load-bearing.</strong> <code>set_gpu_limit(N)</code> marks a stage for GPU; <code>resources.requests</code> on an <code>InferenceService</code> has defaults you will &quot;almost always need to customize.&quot; Undersize and pods pend or OOM; oversize and the GPU pool idles — GPU autoscaling for inference is genuinely hard because it compounds utilization, duty cycle, and cold-start factors.</li><li><strong>Nothing is shared between steps by default.</strong> Each container is isolated; step-to-step data needs explicit plumbing — <code>file_outputs</code> (KFP copies to MinIO), a mounted PVC, or cloud object storage. &quot;The file was right there&quot; is the first bug everyone hits.</li><li><strong>GPU must exist before you ask for it.</strong> The cluster needs GPU-enabled node pools configured per your cloud provider; <code>.set_gpu_limit</code> on a CPU-only cluster schedules to nowhere.</li><li><strong>Notebooks are a stage, not a home.</strong> The designed flow: explore in JupyterHub on-cluster, containerize the function (<code>func_to_container_op</code>) or the whole notebook image, compile, run. Skipping the containerize step leaves you with a demo, not a pipeline.</li></ul><p>Failure modes harvested from the book&#39;s walkthroughs:</p><table tabindex="0"><thead><tr><th>Failure mode</th><th>Mechanism</th><th>Guard</th></tr></thead><tbody><tr><td>Step output &quot;disappears&quot;</td><td>Isolated container FS; no <code>file_outputs</code> declared</td><td>Declare every output path; artifacts land in MinIO</td></tr><tr><td>Recurring run at the wrong hour</td><td>Frequency-only scheduling; start time anchors to creation time</td><td>Create the recurring run at the hour you want it to fire</td></tr><tr><td>Unpinned components drift</td><td><code>load_component</code> fetches the pipelines repo <em>master</em> branch by default</td><td><code>load_component_from_file</code> against a downloaded release tag</td></tr><tr><td>Params lost between steps</td><td>Executor-specific param passing (k8sapi = files only)</td><td>Check <code>containerRuntimeExecutor</code> on your platform</td></tr><tr><td>Silent DSL breakage</td><td>Naming quirk: camelCase op names error; snake_case required</td><td>Lint the compiled YAML before uploading</td></tr><tr><td>Canary that can&#39;t route</td><td><code>canaryTrafficPercent</code> needs Istio/Knative healthy</td><td>Verify the service plane before trusting the split</td></tr></tbody></table><h2 id="ci-cd-for-ml-three-things-under-test-not-one" tabindex="-1">CI/CD for ML: three things under test, not one <a class="header-anchor" href="#ci-cd-for-ml-three-things-under-test-not-one" aria-label="Permalink to &quot;CI/CD for ML: three things under test, not one&quot;">​</a></h2><p>Software CI tests code. ML CI has three test surfaces, and the pyramid layers them:</p>',18)),(i(),o(d,null,{default:t(()=>[n(r,{id:"mermaid-930",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20CI%5B%22Continuous%20Integration%20%E2%80%94%20on%20every%20commit%22%5D%0A%20%20%20%20%20%20%20%20UT%5B%22Unit%20tests%3A%20transform%20logic%2C%20model%20code%20shapes%2C%20NaN%20and%20edge%20handling%22%5D%0A%20%20%20%20%20%20%20%20DT%5B%22Data%20tests%3A%20feature%20engineering%20correctness%2C%20types%2C%20ranges%2C%20non-empty%22%5D%0A%20%20%20%20%20%20%20%20MT%5B%22Model%20tests%3A%20metrics%20above%20baseline%2C%20per-slice%20accuracy%2C%20bias%20checks%22%5D%0A%20%20%20%20%20%20%20%20IT%5B%22Infra%20tests%3A%20pipeline%20compiles%2C%20model%20loads%20on%20the%20serving%20binary%22%5D%0A%20%20%20%20%20%20%20%20DEP%5B%22Deploy%20pipeline%20definition%20%E2%86%92%20prod%20orchestrator%22%5D%0A%20%20%20%20%20%20%20%20TR2%5B%22Pipeline%20runs%3A%20data%20%2B%20model%20validation%20gates%20fire%22%5D%0A%20%20%20%20%20%20%20%20PD%5B%22Progressive%20delivery%3A%20shadow%20%E2%86%92%20canary%20%E2%86%92%20full%2C%20or%20blue-green%22%5D%0A%20%20%20%20end%0A%20%20%20%20CI%20--%3E%20CD%0A%20%20%20%20UT%20--%3E%20DT%20--%3E%20MT%20--%3E%20IT%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[s(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=a('<p>What changes relative to app CI:</p><ul><li><strong>Data unit tests</strong> aren&#39;t the same as pipeline data validation — these check that <em>feature engineering code</em> computes correctly: scales are applied, one-hot vectors are right, embeddings generate, columns have the right type and range.</li><li><strong>Model tests</strong> assert floor metrics: accuracy/AUC above a baseline <em>and</em> above thresholds per important slice. A model that passes overall but fails a slice is a failed build.</li><li><strong>Mocks matter differently</strong>: synthetic test data should cover the edges and corners of the feature space, occupying roughly the same region as real data but sparse — you&#39;re testing behavior, not retraining.</li><li><strong>CD deploys the pipeline, not just the model.</strong> The crucial ML shift: you deploy a <em>training pipeline that continuously produces models</em>, not a frozen artifact. The pipeline&#39;s own triggers (schedule, new-data signal, decay detection) drive retraining.</li></ul><p>This is the maturity ladder (the Google-derived MLOps levels the book uses):</p><table tabindex="0"><thead><tr><th>Level</th><th>What&#39;s automated</th><th>The signature gap</th></tr></thead><tbody><tr><td>0</td><td>Nothing — manual notebook → hand-off to engineers</td><td>Retraining is a project; skew via manual handoff is endemic</td></tr><tr><td>1</td><td>The training pipeline itself: triggers, validation, deploy of each new model</td><td>The pipeline code still ships manually — no CI for pipeline changes</td></tr><tr><td>2</td><td>Full CI/CD: pipeline code is built, tested, deployed like software</td><td>— (aspirational for most orgs)</td></tr></tbody></table><p>The jump that hurts is 0 → 1; the jump that <em>pays</em> is 1 → 2, because it makes &quot;improving the pipeline&quot; as safe as retraining the model.</p><h2 id="the-monitoring-hand-off-—-where-the-pipeline-ends-and-begins-again" tabindex="-1">The monitoring hand-off — where the pipeline ends and begins again <a class="header-anchor" href="#the-monitoring-hand-off-—-where-the-pipeline-ends-and-begins-again" aria-label="Permalink to &quot;The monitoring hand-off — where the pipeline ends and begins again&quot;">​</a></h2><p>A training pipeline doesn&#39;t end at Pusher; it ends at a feedback contract with the serving side:</p>',7)),(i(),o(d,null,{default:t(()=>[n(r,{id:"mermaid-1018",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20S%5B%22Serving%3A%20predictions%20%2B%20request%20features%20logged%22%5D%20--%3E%20MON%5B%22Monitor%3A%20input%20stats%2C%20prediction%20stats%2C%20sliced%20metrics%2C%20label%20comparison%20when%20available%22%5D%0A%20%20%20%20MON%20--%3E%7C%22data%20or%20concept%20drift%20detected%22%7C%20TRIG%5B%22Trigger%3A%20retrain%22%5D%0A%20%20%20%20MON%20--%3E%7C%22infra%20metrics%3A%20latency%2C%20errors%22%7C%20OPS%5B%22Platform%20alerting%22%5D%0A%20%20%20%20TRIG%20--%3E%20EG2%5B%22ExampleGen%20%E2%80%94%20next%20pipeline%20run%22%5D%0A%20%20%20%20S%20-.-%3E%7C%22ground%20truth%20labels%20when%20they%20arrive%22%7C%20LT%5B%22Label%20store%20%E2%86%92%20next%20training%20set%22%5D%0A%20%20%20%20LT%20--%3E%20EG2%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[s(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=a('<p>The hand-off has three payloads:</p><ul><li><strong>Logged prediction requests</strong> — feature vectors as served. This is the raw material for detecting <em>serving-side</em> distribution shift and the skew comparisons above. If serving logs nothing, skew detection has no second dataset.</li><li><strong>Ground-truth labels when they arrive</strong> — late labels feed both true-accuracy monitoring and the <em>next training set</em>. The label-delay story from <a href="/Data-Knowledge/system-design/ml-systems.html">ML &amp; GenAI System Design</a> is what determines whether decay detection is days-fast (proxies) or weeks-slow (real labels).</li><li><strong>A retraining trigger</strong> — monitor-decided, not calendar-decided. Scheduled retrains handle seasonality; drift-triggered retrains handle the world changing on its own schedule. Mature pipelines run both.</li></ul><p>This closes the loop: the pipeline exists because models decay, monitoring detects decay, and the trigger restarts the pipeline. A training pipeline with no monitoring hand-off is a deploy script with extra steps — it can ship a model but can&#39;t tell you when it&#39;s wrong.</p><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',4)),n(l,{questions:[{q:"In a TFX-style pipeline, which component emits the artifact that every downstream validation gate depends on?",options:["StatisticsGen","Pusher","ExampleGen","SchemaGen"],correct:3,explain:"SchemaGen infers the schema — types, presence, domains — that ExampleValidator checks anomalies against and Transform builds on. StatisticsGen produces the stats, but the schema is the contract."},{q:"Serving features arrive as integers where training saw floats. Which skew type is this?",options:["Feature skew","Schema skew","Distribution skew","Concept drift"],correct:1,explain:"Schema skew = training and serving data do not conform to the same schema. Feature skew compares same-entity values; distribution skew compares distribution shape."},{q:"Why does the Transform component prevent training-serving skew better than a preprocessing script?",options:["It caches features in a store","It runs faster on Beam","It validates the schema","It ships the transform graph prepended to the SavedModel, so serving applies the identical computation"],correct:3,explain:"The transform graph — including full-pass analyzer results frozen as constants — becomes part of the model artifact, so training and serving execute the same ops by construction."},{q:"A candidate model beats the incumbent on overall accuracy but fails badly on one customer region. Which gate should stop it?",options:["StatisticsGen","Pusher","Evaluator","InfraValidator"],correct:2,explain:"The Evaluator checks metrics against the baseline and per data slice — a model better on average but broken on a segment must not be blessed. InfraValidator only checks the model loads on the serving binary."},{q:"What distinguishes MLOps level 1 from level 2?",options:["Level 1 automates the training pipeline; level 2 adds CI/CD for the pipeline code itself","Level 1 uses Airflow; level 2 uses Kubeflow","Level 1 has monitoring; level 2 adds a feature store","Level 1 trains weekly; level 2 trains daily"],correct:0,explain:"Level 1 automates continuous training and model delivery. Level 2 wraps the pipeline definition itself in CI/CD — the pipeline code is built, tested, and deployed like software."},{q:"What is the correct unit to register, promote, and roll back in a model registry?",options:["The Docker image only","The training notebook + weights","Model artifact + transform/preprocessing + input contract together","Just the model weights"],correct:2,explain:"A model without its preprocessing and feature schema is a half-version — rollback to it is unsafe because nobody knows what inputs it expects. The versioned unit is the whole serving contract."}]}),n(l,{questions:[{q:"In Kubeflow Pipelines, how does data actually move between two pipeline steps?",options:["file_outputs shuttled through object storage like MinIO","Env vars between pods","In-memory XComs on the Argo controller","Shared container filesystem"],correct:0,explain:"Every step is an isolated container — nothing is shared by default. KFP copies declared file_outputs into object storage (MinIO) so the next stage can mount or download them. The first bug everyone hits is an output that was never declared."},{q:"An InferenceService has canaryTrafficPercent set to 0 with a canary predictor defined. What did you just deploy?",options:["A blue-green deployment","Nothing — zero traffic means the canary never starts","A pinned deployment with an addressable experimental endpoint","A percentage-split canary"],correct:2,explain:"Zero percent gives a pinned deployment: production traffic stays on default, but the canary endpoint is addressable for experimental traffic. Above zero it becomes a true canary you ratchet toward 100; default-only is plain blue-green."},{q:"Your team wants mature cron scheduling with catchup and backfill, and the training pipeline is one stage of an existing data DAG. Kubeflow or Airflow?",options:["Both — run the pipeline twice","Airflow — scheduling maturity and DAG fit win","Kubeflow — better artifact lineage wins","Neither — notebooks are fine"],correct:1,explain:"Kubeflow recurring runs are frequency-only — you specify how often, not when. Kubeflow wins on per-run semantics (artifact lineage, step caching, GPU scheduling); Airflow wins on calendar semantics and fitting training into an existing data DAG."}]}),e[11]||(e[11]=a('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><strong>Machine Learning Production Systems</strong> — Robert Crowe, Hannes Hapke, Emily Caveness, Di Zhu, Catherine Nelson (O&#39;Reilly, 2024), <a href="https://www.oreilly.com/library/view/machine-learning-production/9781098156008/" target="_blank" rel="noreferrer">oreilly.com</a> — the source for this chapter: TFX component deep-dives, MLOps levels, skew taxonomy.</li><li><a href="https://www.tensorflow.org/tfx/guide" target="_blank" rel="noreferrer">TFX User Guide</a> — component APIs, artifact model, and orchestrator wiring for the real thing.</li><li><a href="https://www.tensorflow.org/tfx/data_validation/get_started" target="_blank" rel="noreferrer">TensorFlow Data Validation</a> — schema inference, anomaly detection, and the skew/drift comparators.</li><li><a href="https://www.kubeflow.org/docs/components/pipelines/" target="_blank" rel="noreferrer">Kubeflow Pipelines docs</a> — the Kubernetes-native orchestration side.</li><li><strong>Kubeflow for Machine Learning: From Lab to Production</strong> — Trevor Grant, Holden Karau, Boris Lublinsky, Richard Liu, Ilan Filonenko (O&#39;Reilly, 2020), <a href="https://www.oreilly.com/library/view/kubeflow-for-machine/9781492050117/" target="_blank" rel="noreferrer">oreilly.com</a> — source for the Kubeflow sections: platform anatomy, KFP-on-Argo DSL, Katib tuning, KFServing canary strategies.</li><li><a href="https://cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning" target="_blank" rel="noreferrer">Google Cloud: MLOps continuous delivery and automation pipelines</a> — the original level 0/1/2 architecture writeup.</li><li><a href="https://mlflow.org/docs/latest/model-registry.html" target="_blank" rel="noreferrer">MLflow Model Registry</a> — the registry/stage model if you are not on TFX.</li></ul>',2))])}const T=h(u,[["render",m]]);export{k as __pageData,T as default};
